import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DIRECTIONS = ['입금', '출금'];
const CYCLES = ['MONTHLY', 'QUARTERLY', 'YEARLY', 'ONCE'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^\d+$/;
const AMOUNT_PATTERN = /^\d+(\.\d{1,2})?$/;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_FIXED_FUND', message);
}

function text(value: unknown): string {
  if (value === null || value === undefined) {
    return '';
  }
  return String(value).trim();
}

function parseBody(data: Record<string, unknown>) {
  const fixedFundName = text(data.fixedFundName);
  if (fixedFundName === '' || fixedFundName.length > 200) {
    throw invalid('고정자금명을 200자 이내로 입력해 주세요.');
  }
  const fundSubjectId = text(data.fundSubjectId);
  if (!ID_PATTERN.test(fundSubjectId)) {
    throw invalid('자금과목을 선택해 주세요.');
  }
  const amount = text(data.amount);
  if (!AMOUNT_PATTERN.test(amount) || Number(amount) <= 0) {
    throw invalid('금액은 0보다 큰 숫자(소수 2자리까지)로 입력해 주세요.');
  }
  const cashDirection = text(data.cashDirection);
  if (!DIRECTIONS.includes(cashDirection)) {
    throw invalid('입출금 구분을 선택해 주세요.');
  }
  const occurrenceCycle = text(data.occurrenceCycle);
  if (!CYCLES.includes(occurrenceCycle)) {
    throw invalid('발생 주기를 선택해 주세요.');
  }
  const startDate = text(data.startDate);
  if (!DATE_PATTERN.test(startDate)) {
    throw invalid('발생 시작일을 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  const endText = text(data.endDate);
  let endDate: string | null = null;
  if (endText !== '') {
    if (!DATE_PATTERN.test(endText)) {
      throw invalid('발생 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (endText < startDate) {
      throw invalid('발생 종료일은 시작일 이후여야 합니다.');
    }
    endDate = endText;
  }
  return { fixedFundName, fundSubjectId, amount, cashDirection, occurrenceCycle, startDate, endDate };
}

function parseId(value: unknown): string {
  const id = text(value);
  if (!ID_PATTERN.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '고정자금 ID 형식이 올바르지 않습니다.');
  }
  return id;
}

@Controller('api/v1')
export class FnSfr00906Controller {
  @Get('/fixed-funds')
  async listFixedFunds(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const subjectText = text(query.fundSubjectId);
    if (subjectText !== '' && !ID_PATTERN.test(subjectText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자금과목 형식이 올바르지 않습니다.');
    }
    const directionText = text(query.cashDirection);
    if (directionText !== '' && !DIRECTIONS.includes(directionText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '입출금 구분이 올바르지 않습니다.');
    }
    const pageText = text(query.page);
    const page = pageText === '' ? 0 : Number(pageText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const sizeText = text(query.size);
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:fundSubjectId AS bigint) IS NULL OR fund_subject_id = CAST(:fundSubjectId AS bigint))\n' +
        '  AND (CAST(:cashDirection AS varchar) IS NULL OR cash_direction = CAST(:cashDirection AS varchar))';
      const filter = {
        fundSubjectId: subjectText === '' ? null : subjectText,
        cashDirection: directionText === '' ? null : directionText,
      };
      const items = await db.query(
        'SELECT fixed_fund_id AS "fixedFundId",\n' +
          '  fixed_fund_name AS "fixedFundName",\n' +
          '  fund_subject_id AS "fundSubjectId",\n' +
          '  amount AS "amount",\n' +
          '  cash_direction AS "cashDirection",\n' +
          '  occurrence_cycle AS "occurrenceCycle",\n' +
          "  to_char(start_date, 'YYYY-MM-DD') AS \"startDate\",\n" +
          "  to_char(end_date, 'YYYY-MM-DD') AS \"endDate\"\n" +
          'FROM fixed_fund\n' +
          where +
          '\nORDER BY fixed_fund_id DESC\n' +
          'LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...filter, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM fixed_fund\n' + where,
        filter,
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/fixed-funds')
  @HttpCode(200)
  async createFixedFund(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const input = parseBody(data);
    return transaction(async (db) => {
      const subjects = await db.query(
        'SELECT fund_subject_id FROM fund_subject WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)',
        { fundSubjectId: input.fundSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목이 존재하지 않습니다.');
      }
      const rows = await db.query(
        'INSERT INTO fixed_fund (fixed_fund_name, fund_subject_id, amount, cash_direction,\n' +
          '  occurrence_cycle, start_date, end_date, created_at, updated_at)\n' +
          'VALUES (:fixedFundName, CAST(:fundSubjectId AS bigint), CAST(:amount AS numeric), :cashDirection,\n' +
          '  :occurrenceCycle, CAST(:startDate AS date), CAST(:endDate AS date), now(), now())\n' +
          'RETURNING fixed_fund_id AS "fixedFundId"',
        input,
      );
      return rows[0];
    });
  }

  @Put('/fixed-funds/:fixedFundId')
  async updateFixedFund(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const fixedFundId = parseId(req.params['fixedFundId']);
    const data = checks.inputOf(req.body);
    const input = parseBody(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT fixed_fund_id FROM fixed_fund WHERE fixed_fund_id = CAST(:fixedFundId AS bigint)',
        { fixedFundId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FIXED_FUND_NOT_FOUND', '고정자금이 존재하지 않습니다.');
      }
      const subjects = await db.query(
        'SELECT fund_subject_id FROM fund_subject WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)',
        { fundSubjectId: input.fundSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목이 존재하지 않습니다.');
      }
      const rows = await db.query(
        'UPDATE fixed_fund SET fixed_fund_name = :fixedFundName,\n' +
          '  fund_subject_id = CAST(:fundSubjectId AS bigint),\n' +
          '  amount = CAST(:amount AS numeric),\n' +
          '  cash_direction = :cashDirection,\n' +
          '  occurrence_cycle = :occurrenceCycle,\n' +
          '  start_date = CAST(:startDate AS date),\n' +
          '  end_date = CAST(:endDate AS date),\n' +
          '  updated_at = now()\n' +
          'WHERE fixed_fund_id = CAST(:fixedFundId AS bigint)\n' +
          'RETURNING fixed_fund_id AS "fixedFundId"',
        { ...input, fixedFundId },
      );
      return rows[0];
    });
  }

  @Delete('/fixed-funds/:fixedFundId')
  async deleteFixedFund(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const fixedFundId = parseId(req.params['fixedFundId']);
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM fixed_fund WHERE fixed_fund_id = CAST(:fixedFundId AS bigint)',
        { fixedFundId },
      );
      if (count === 0) {
        throw new ApiError(404, 'FIXED_FUND_NOT_FOUND', '고정자금이 존재하지 않습니다.');
      }
      return {};
    });
  }
}

