import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const CYCLE_OPTIONS: [string, string][] = [
  ['MONTHLY', '매월'],
  ['QUARTERLY', '분기'],
  ['YEARLY', '매년'],
  ['ONCE', '1회'],
];
const DIRECTION_OPTIONS: [string, string][] = [
  ['입금', '입금'],
  ['출금', '출금'],
];

function cycleName(value: unknown): string {
  const found = CYCLE_OPTIONS.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

interface FormProps {
  role: string;
  row: Row | null;
  onDone: (message: string) => void;
}

function FixedFundForm({ role, row, onDone }: FormProps) {
  const [f, setF] = useState<Row>(
    row ?? { fixedFundName: '', fundSubjectId: '', amount: '', cashDirection: '', occurrenceCycle: '', startDate: '', endDate: '' },
  );
  const set = (key: string, value: unknown) => setF({ ...f, [key]: value });
  const submit = async () => {
    if (!f.fixedFundName || f.fundSubjectId === '' || f.amount === '' || !f.cashDirection || !f.occurrenceCycle || !f.startDate) {
      throw new Error('필수 항목을 모두 입력해 주세요.');
    }
    const body: Row = {
      fixedFundName: f.fixedFundName,
      fundSubjectId: f.fundSubjectId,
      amount: f.amount,
      cashDirection: f.cashDirection,
      occurrenceCycle: f.occurrenceCycle,
      startDate: f.startDate,
      endDate: f.endDate ? f.endDate : undefined,
    };
    if (row) {
      await call('PUT', '/fixed-funds/' + row.fixedFundId, role, body);
      onDone('고정자금을 수정했습니다.');
    } else {
      await call('POST', '/fixed-funds', role, body);
      onDone('고정자금을 등록했습니다.');
    }
  };
  return (
    <Form onSubmit={submit} submit={row ? '수정' : '등록'}>
      <Field label='고정자금명' required wide>
        <TextInput value={f.fixedFundName} onChange={(v) => set('fixedFundName', v)} />
      </Field>
      <Field label='자금과목' required>
        <LookupSelect table='fund_subject' role={role} value={f.fundSubjectId} onChange={(v) => set('fundSubjectId', v)} />
      </Field>
      <Field label='금액' required>
        <NumberInput value={f.amount} onChange={(v) => set('amount', v)} />
      </Field>
      <Field label='입출금 구분' required>
        <Select value={f.cashDirection} onChange={(v) => set('cashDirection', v)} options={DIRECTION_OPTIONS} />
      </Field>
      <Field label='발생 주기' required>
        <Select value={f.occurrenceCycle} onChange={(v) => set('occurrenceCycle', v)} options={CYCLE_OPTIONS} />
      </Field>
      <Field label='발생 시작일' required>
        <DateInput value={f.startDate} onChange={(v) => set('startDate', v)} />
      </Field>
      <Field label='발생 종료일' hint='비우면 종료일 없이 계속 발생합니다.'>
        <DateInput value={f.endDate} onChange={(v) => set('endDate', v)} />
      </Field>
    </Form>
  );
}

export default function FnSfr00906Page({ role, notify }: PageProps) {
  const [subjectId, setSubjectId] = useState<number | string>('');
  const [direction, setDirection] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<'none' | 'create' | 'detail' | 'edit' | 'delete'>('none');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/fixed-funds', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const rows = data ? data.items : [];
  const sum = (dir: string) =>
    rows.filter((r) => r.cashDirection === dir).reduce((acc, r) => acc + Number(r.amount ?? 0), 0);

  const close = () => {
    setMode('none');
    setSelected(null);
  };
  const done = (message: string) => {
    close();
    notify(message);
    reload();
  };
  const search = () => {
    setPage(0);
    setApplied({ fundSubjectId: subjectId, cashDirection: direction });
  };
  const reset = () => {
    setSubjectId('');
    setDirection('');
    setPage(0);
    setApplied({});
  };
  const remove = async () => {
    if (!selected) {
      return;
    }
    await call('DELETE', '/fixed-funds/' + selected.fixedFundId, role);
    done('고정자금을 삭제했습니다.');
  };

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>현재 쪽 합계</h2>
        <Tiles
          items={[
            ['전체 건수', <Num value={data ? data.total : 0} />],
            ['입금 합계', <Num value={sum('입금')} />],
            ['출금 합계', <Num value={sum('출금')} />],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>고정자금</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='자금과목'>
            <LookupSelect table='fund_subject' role={role} value={subjectId} onChange={setSubjectId} placeholder='전체' />
          </Field>
          <Field label='입출금 구분'>
            <Select value={direction} onChange={setDirection} options={DIRECTION_OPTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type='button' onClick={() => setMode('create')}>
            고정자금 등록
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty='등록된 고정자금이 없습니다.'
          onRowClick={(r) => {
            setSelected(r);
            setMode('detail');
          }}
          columns={[
            { key: 'fixedFundName', label: '고정자금명' },
            { key: 'fundSubjectId', label: '자금과목', render: (r) => <RefName table='fund_subject' role={role} value={r.fundSubjectId} /> },
            { key: 'amount', label: '금액', render: (r) => <Num value={r.amount} /> },
            { key: 'cashDirection', label: '입출금 구분', render: (r) => <Badge value={r.cashDirection} /> },
            { key: 'occurrenceCycle', label: '발생 주기', render: (r) => cycleName(r.occurrenceCycle) },
            { key: 'startDate', label: '발생 시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '발생 종료일', render: (r) => <DateText value={r.endDate} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {mode === 'create' ? (
        <Drawer title='고정자금 등록' onClose={close}>
          <FixedFundForm role={role} row={null} onDone={done} />
        </Drawer>
      ) : null}
      {mode === 'detail' && selected ? (
        <Drawer title='고정자금 상세' onClose={close}>
          <Pairs
            items={[
              ['고정자금명', String(selected.fixedFundName ?? '')],
              ['자금과목', <RefName table='fund_subject' role={role} value={selected.fundSubjectId} />],
              ['금액', <Num value={selected.amount} />],
              ['입출금 구분', <Badge value={selected.cashDirection} />],
              ['발생 주기', cycleName(selected.occurrenceCycle)],
              ['발생 시작일', <DateText value={selected.startDate} />],
              ['발생 종료일', <DateText value={selected.endDate} />],
            ]}
          />
          <button type='button' onClick={() => setMode('edit')}>
            수정
          </button>
          <button type='button' onClick={() => setMode('delete')}>
            삭제
          </button>
        </Drawer>
      ) : null}
      {mode === 'edit' && selected ? (
        <Drawer title='고정자금 수정' onClose={close}>
          <FixedFundForm role={role} row={selected} onDone={done} />
        </Drawer>
      ) : null}
      {mode === 'delete' && selected ? (
        <Drawer title='고정자금 삭제' onClose={close}>
          <Form onSubmit={remove} submit='삭제' danger note={'\'' + String(selected.fixedFundName ?? '') + '\' 고정자금을 삭제합니다.'} />
        </Drawer>
      ) : null}
    </div>
  );
}
